"""Campaign record adapter and revision-aware evidence ledger.

A logical data record is 14 string fields. This module parses one record
into a compact tuple, rejecting malformed rows with `Invalid`, and
reconciles `(type,id)` identities across publication revisions.

Record tuple layout:

    0 kind        0 icmp, 1 application
    1 id          record identity string
    2 revision    visible integer revision
    3 published   publication time
    4 content     canonical semantic content (op and every typed put field)
    5 lease       lease identifier (puts)
    6 event       event time inside the lease interval (puts)
    7 target      documentation target network integer (puts)
    8 probe       (subnet, is_canary, ordinal) for icmp puts
    9 responder   responder network integer or None for icmp puts
   10 result      0 echo/open, 1 error/closed, 2 timeout
   11 service     service identifier for application puts
   12 attempt     application attempt integer
   13 payload     decoded application payload bytes
"""
from common import ID, Invalid, address, decimal, decode64

ICMP = 0
APP = 1

ECHO = 0
ERROR = 1
TIMEOUT = 2

OPEN = 0
CLOSED = 1

ICMP_RESULTS = {'echo':ECHO,'error':ERROR,'timeout':TIMEOUT}
APP_RESULTS = {'open':OPEN,'closed':CLOSED,'timeout':TIMEOUT}

MAX_REVISION = 10**9
MAX_ATTEMPT = 10**6
MAX_PAYLOAD = 65536


def _probe(text):
    """Parse `subnet/c` or `subnet/iN`; returns (subnet, canary, ordinal)."""
    if not isinstance(text,str) or len(text)>40:
        return None
    slash=text.find('/')
    if slash<0:
        return None
    left=text[:slash]
    right=text[slash+1:]
    if not left or not left.isascii() or not left.isdecimal():
        return None
    subnet=_plain(left)
    if subnet is None or subnet>255:
        return None
    if right=='c':
        return (subnet,True,0)
    if len(right)>1 and right[0]=='i' and right[1:].isascii() and right[1:].isdecimal():
        ordinal=_plain(right[1:])
        if ordinal is None or ordinal<1 or ordinal>32:
            return None
        return (subnet,False,ordinal)
    return None


def _plain(digits):
    """Integer value of an ASCII decimal string, tolerant of leading zeros."""
    body=digits.lstrip('0')
    if len(body)>16:
        return None
    return int(body) if body else 0


def parse_record(values,context,lookup):
    """Validate one logical CSV data record; raises Invalid when malformed."""
    if len(values)!=14:
        raise Invalid('wrong field count')
    (kind,id_text,revision,published,op,lease,event,probe,target,responder,
     result,service,attempt,payload)=values
    if kind=='icmp':
        family=ICMP
    elif kind=='app':
        family=APP
    else:
        raise Invalid('unknown record type')
    if type(id_text) is not str or ID.fullmatch(id_text) is None:
        raise Invalid('invalid record id')
    rev=decimal(revision,MAX_REVISION)
    pub=decimal(published)
    if op=='delete':
        if (lease or event or probe or target or responder or result
                or service or attempt or payload):
            raise Invalid('delete with trailing fields')
        return (family,id_text,rev,pub,(1,),None,0,0,None,None,TIMEOUT,None,0,b'')
    if op!='put':
        raise Invalid('unknown op')
    info=context['leases'].get(lease)
    if info is None:
        raise Invalid('unknown lease')
    moment=decimal(event)
    if moment<info['start'] or moment>=info['end'] or moment>pub:
        raise Invalid('event outside lease interval')
    target_value=address(target)
    if family==ICMP:
        if service or attempt or payload:
            raise Invalid('icmp row with application fields')
        key=_probe(probe)
        if key is None:
            raise Invalid('invalid probe')
        planned=lookup.get((lease,key))
        if planned is None:
            raise Invalid('probe outside lease manifest')
        if planned[0]!=target_value:
            raise Invalid('probe target mismatch')
        if result=='timeout':
            responder_value=None; code=TIMEOUT
        elif result in ('echo','error'):
            responder_value=address(responder); code=ICMP_RESULTS[result]
        else:
            raise Invalid('invalid icmp result')
        content=(0,lease,moment,target_value,key,responder_value,code)
        return (ICMP,id_text,rev,pub,content,lease,moment,target_value,key,
                responder_value,code,None,0,b'')
    if probe or responder:
        raise Invalid('application row with icmp fields')
    kind_of_service=context['services'].get(service)
    if kind_of_service is None:
        raise Invalid('unknown service')
    attempts=decimal(attempt,MAX_ATTEMPT)
    if result=='open':
        code=OPEN
    elif result=='closed':
        code=CLOSED
        if payload:
            raise Invalid('closed row with payload')
    elif result=='timeout':
        code=TIMEOUT
        if payload:
            raise Invalid('timeout row with payload')
    else:
        raise Invalid('invalid application result')
    body=decode64(payload) if payload else b''
    if len(body)>MAX_PAYLOAD:
        raise Invalid('payload too large')
    if kind_of_service=='tcp' and body:
        raise Invalid('tcp row with payload')
    content=(0,lease,moment,target_value,service,attempts,code,body)
    return (APP,id_text,rev,pub,content,lease,moment,target_value,None,None,
            code,service,attempts,body)


class Ledger:
    """Revision-aware reconciliation of `(type,id)` record identities."""

    def __init__(self,records):
        self.records=records

    def at(self,time):
        """Reconcile every identity visible at `time`.

        Returns `(live, ledger)` where `live` holds one representative row
        per live identity and `ledger` holds the live/deleted/conflict
        identity counts.
        """
        best={}
        rep={}
        multi=set()
        for row in self.records:
            if row[3]>time:
                continue
            key=(row[0],row[1])
            revision=row[2]
            seen=best.get(key)
            if seen is None:
                best[key]=revision
                rep[key]=row
            elif revision>seen:
                best[key]=revision
                rep[key]=row
                multi.discard(key)
            elif revision==seen and rep[key][4]!=row[4]:
                multi.add(key)
        live=[]
        live_count=deleted_count=conflict_count=0
        for key,row in rep.items():
            if key in multi:
                conflict_count+=1
            elif row[4][0]==0:
                live_count+=1
                live.append(row)
            else:
                deleted_count+=1
        return live,{'live':live_count,'deleted':deleted_count,
                     'conflict':conflict_count}
